 public struct Quaternion {public float x,y,z,w;public Quaternion(float x,float y,float z,float w){this.x=x;this.y=y;this.z=z;this.w=w;}public static Quaternion identity=>new Quaternion(0,0,0,1);public static Quaternion LookRotation(Vector3 f,Vector3 u=default){f=f.normalized;float yaw=MathF.Atan2(f.x,f.z)*180/MathF.PI;float pitch=-MathF.Atan2(f.y,MathF.Sqrt(f.x*f.x+f.z*f.z))*180/MathF.PI;return Euler(pitch,yaw,0);}public static Quaternion Inverse(Quaternion q)=>new Quaternion(-q.x,-q.y,-q.z,q.w);public static Vector3 operator*(Quaternion q,Vector3 v){Vector3 u=new Vector3(q.x,q.y,q.z);return 2*Vector3.Dot(u,v)*u+(q.w*q.w-Vector3.Dot(u,u))*v+2*q.w*Vector3.Cross(u,v);}public static Quaternion operator*(Quaternion a,Quaternion b)=>new Quaternion(a.w*b.x+a.x*b.w+a.y*b.z-a.z*b.y,a.w*b.y-a.x*b.z+a.y*b.w+a.z*b.x,a.w*b.z+a.x*b.y-a.y*b.x+a.z*b.w,a.w*b.w-a.x*b.x-a.y*b.y-a.z*b.z);public static Quaternion Euler(Vector3 v)=>Euler(v.x,v.y,v.z);public static Quaternion Euler(float x,float y,float z){float r=MathF.PI/360;return new Quaternion(0,MathF.Sin(y*r),0,MathF.Cos(y*r))*new Quaternion(MathF.Sin(x*r),0,0,MathF.Cos(x*r))*new Quaternion(0,0,MathF.Sin(z*r),MathF.Cos(z*r));}public static Quaternion RotateTowards(Quaternion a,Quaternion b,float t){float d=MathF.Abs(a.x*b.x+a.y*b.y+a.z*b.z+a.w*b.w);float angle=2*MathF.Acos(Math.Clamp(d,-1,1))*180/MathF.PI;return Slerp(a,b,angle<.001f?1:Math.Min(1,t/angle));}public static Quaternion Slerp(Quaternion a,Quaternion b,float t){float d=a.x*b.x+a.y*b.y+a.z*b.z+a.w*b.w;if(d<0){b=new Quaternion(-b.x,-b.y,-b.z,-b.w);d=-d;}float x=1-t,y=t;if(d<.9995f){float angle=MathF.Acos(d),s=MathF.Sin(angle);x=MathF.Sin((1-t)*angle)/s;y=MathF.Sin(t*angle)/s;}var q=new Quaternion(a.x*x+b.x*y,a.y*x+b.y*y,a.z*x+b.z*y,a.w*x+b.w*y);float length=MathF.Sqrt(q.x*q.x+q.y*q.y+q.z*q.z+q.w*q.w);return new Quaternion(q.x/length,q.y/length,q.z/length,q.w/length);}}
